/* ---------- Model compare ---------- */
.mcx{display:flex;flex-direction:column;gap:12px}
.mcx-cols{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
@media (max-width:720px){.mcx-cols{grid-template-columns:1fr}}
.mcx-c{display:flex;flex-direction:column;min-height:252px;min-width:0;transition:box-shadow .35s,opacity .4s}
.mcx-c.win{box-shadow:0 0 0 1.5px var(--accent-mark,var(--accent)),var(--shadow)}
.mcx-c.lose{opacity:.55}
.mcx-c.enter{animation-duration:.5s}
.mcx-h{display:flex;align-items:center;gap:6px;height:46px;padding:0 6px;border-bottom:1px solid var(--line)}
.mcx-sel{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 8px 0 6px;border-radius:9px;font-size:13px;font-weight:500;min-width:0;transition:background .2s}
.mcx-sel:hover,.mcx-sel[aria-expanded="true"]{background:var(--chip)}
.mcx-sel>.i{color:var(--muted)}
.mcx-mk{width:20px;height:20px;border-radius:6px;display:grid;place-items:center;font-size:10px;font-weight:500;color:#fff;flex:none}
.mcx-x{width:26px;height:26px;margin-left:auto;color:var(--muted)}
.mcx-o{flex:1;display:flex;flex-direction:column;gap:10px;padding:12px}
.mcx-o .bub{font-size:13px;padding:7px 11px;border-radius:14px;max-width:92%}
.mcx-a{font-size:13.5px;line-height:1.55;color:var(--fg);display:flex;flex-direction:column;gap:6px}
.mcx-a .w{animation:mcw .4s var(--ease) both}
@keyframes mcw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.mcx-a .ph{color:var(--muted);font-size:12.5px}
.mcx-a .wk{display:inline-flex;align-items:center;gap:7px;font-size:12.5px;color:var(--muted)}
.mcx-a .wk .think{color:var(--accent-fg,var(--accent))}
.mcx-f{display:flex;align-items:center;gap:8px;height:44px;padding:0 8px 0 12px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}
.mcx-m{display:inline-flex;gap:10px;white-space:nowrap}
.mcx-m span{cursor:default;display:inline-flex;align-items:center;gap:4px;transition:color .3s}
.mcx-m .best{color:var(--ok);font-weight:500}
.mcx-pick{margin-left:auto}
.mcx-pop{min-width:250px}
.mcx-pop .mi[disabled]{opacity:.45;cursor:not-allowed}
.mcx-add{border-radius:var(--r-card);box-shadow:inset 0 0 0 1.5px var(--rail);display:flex;align-items:center;justify-content:center;min-height:252px;position:relative;transition:background .2s,box-shadow .2s}
.mcx-add:hover{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--faint)}
.mcx-addb{display:flex;flex-direction:column;align-items:center;gap:6px;font-size:13px;color:var(--fg2);padding:14px 18px;border-radius:14px;transition:background .2s,color .2s}
.mcx-addb:hover,.mcx-addb[aria-expanded="true"]{color:var(--fg)}
.mcx-addb .ic{margin-bottom:2px}
.mcx-addb .ic{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--soft,var(--chip));box-shadow:var(--soft-ring,none);color:var(--fg)}
.mcx-addb .d{font-size:12px;color:var(--muted)}
.mcx-in{display:flex;align-items:center;gap:10px;padding:6px 6px 6px 18px;border-radius:999px;background:var(--surface);box-shadow:var(--shadow);transition:box-shadow .25s}
.mcx-in:focus-within{box-shadow:var(--shadow),0 0 0 4px var(--accent-bg)}
.mcx-q{flex:1;min-width:0;border:0;outline:0;background:none;font:inherit;font-size:13.5px;color:var(--fg)}
.mcx-n{font-size:12px;white-space:nowrap}
.mcx-go{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--ink);color:var(--on-ink);flex:none;transition:opacity .2s,transform .15s}
.mcx-go:active{transform:scale(.92)}
.mcx-go[disabled]{background:var(--rail);color:var(--surface);cursor:not-allowed}

DM.def('model-compare', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{up}', I('up'));
  const MOD = {
    Opus:{ k:'O', c:'var(--c2)', t:'var(--on-ink)', d:'Most capable, slower', ms:2400, tps:38, cost:.021, o:'Pro gives every designer an agent that knows your tokens, so reviews take minutes, not days.' },
    Sonnet:{ k:'S', c:'var(--accent)', t:'var(--on-accent)', d:'Balanced speed and quality', ms:1300, tps:74, cost:.006, o:'Ship polished pages faster with an agent that checks every frame for you.' },
    Haiku:{ k:'H', c:'var(--c3)', t:'#121212', d:'Fastest, lowest cost', ms:600, tps:142, cost:.001, o:'Your design QA, on autopilot.' }
  };
  const generic = { Opus:'Here is a considered take, with the trade-offs spelled out and one clear recommendation at the end.', Sonnet:'Here is a clear, direct answer with the two points that matter most.', Haiku:'Short answer: yes, and here is the one line why.' };
  const cols = $('.mcx-cols', r), q = $('.mcx-q', r), go = $('.mcx-go', r), cnt = $('.mcx-n', r), DEF = q.value, MAX = 3;
  const C = []; let uid = 0, asked = '', busy = 0;
  const menu = (id, cur) => `<div class="pop mcx-pop ${id}" role="menu">${Object.keys(MOD).map(n => `<button class="mi" role="menuitemradio" data-close data-m="${n}" aria-checked="${n === cur}"><span class="mcx-mk" style="background:${MOD[n].c};color:${MOD[n].t}">${MOD[n].k}</span><span>${n}<span class="d">${MOD[n].d}</span></span><span class="ck">${I('check','xs')}</span></button>`).join('')}</div>`;
  /* the empty slot: add a model back, up to three side by side */
  const slot = html(`<div class="mcx-add"><button class="mcx-addb" data-pop=".mcx-pa" data-pop-pos="down" data-pop-align="end" aria-haspopup="menu"><span class="ic">${I('plus','s')}</span>Add a model<span class="d">Compare up to 3</span></button><div class="pop mcx-pop mcx-pa" role="menu"></div></div>`);
  function sync(){
    cnt.textContent = 'Sends to ' + C.length + (C.length > 1 ? ' models' : ' model');
    C.forEach(col => { const x = $('.mcx-x', col.el); x.hidden = C.length < 2; });
    if (C.length < MAX){ cols.appendChild(slot); $('.mcx-pa', slot).innerHTML = Object.keys(MOD).map(n => `<button class="mi" role="menuitem" data-close data-m="${n}"><span class="mcx-mk" style="background:${MOD[n].c};color:${MOD[n].t}">${MOD[n].k}</span><span>${n}<span class="d">${MOD[n].d}</span></span></button>`).join(''); $$('.mcx-pa .mi', slot).forEach(b => b.onclick = () => addCol(b.dataset.m, true)); }
    else slot.remove();
  }
  function head(col){ const m = MOD[col.m]; $('.mcx-sel', col.el).innerHTML = `<span class="mcx-mk" style="background:${m.c};color:${m.t}">${m.k}</span>${col.m}${I('chev-d','xs')}`; $$('.mi', col.el).forEach(x => x.setAttribute('aria-checked', x.dataset.m === col.m)); }
  function addCol(m, fresh){
    const id = 'mcx-p' + (uid++), el = html(`<div class="mcx-c panel"><div class="mcx-h"><button class="mcx-sel" data-pop=".${id}" aria-haspopup="menu"></button><button class="ib mcx-x" aria-label="Remove model" data-tip="Remove">${I('x','xs')}</button></div>${menu(id, m)}<div class="mcx-o"><div class="mcx-a"><span class="ph">Waiting for a prompt</span></div></div><div class="mcx-f"><span class="mcx-m num">No run yet</span><button class="pill soft sm mcx-pick" disabled>Use this</button></div></div>`);
    const col = { m, el, run:0 }; C.push(col); cols.insertBefore(el, slot.parentNode === cols ? slot : null); head(col);
    $$('.mi', el).forEach(x => x.addEventListener('click', () => { if (col.m === x.dataset.m) return; col.m = x.dataset.m; head(col); if (asked) c.run(() => one(col)); }));
    $('.mcx-x', el).onclick = () => { hideTip(); C.splice(C.indexOf(col), 1); col.run++; el.classList.add('leave'); setTimeout(() => { el.remove(); sync(); }, 260); };
    $('.mcx-pick', el).onclick = () => choose(col);
    if (fresh){ enter(el); sync(); if (asked) c.run(() => one(col)); }
    return col;
  }
  function choose(col){
    const on = !col.el.classList.contains('win');
    C.forEach(x => { x.el.classList.toggle('win', on && x === col); x.el.classList.toggle('lose', on && x !== col); $('.mcx-pick', x.el).innerHTML = on && x === col ? I('check','xs') + 'Chosen' : 'Use this'; });
  }
  async function one(col){
    const id = ++col.run, el = col.el, m = MOD[col.m], o = $('.mcx-o', el), f = $('.mcx-m', el), pk = $('.mcx-pick', el);
    C.forEach(x => x.el.classList.remove('win','lose')); C.forEach(x => { const b = $('.mcx-pick', x.el); if (b.textContent === 'Chosen') b.textContent = 'Use this'; });
    pk.disabled = true; f.textContent = 'Running'; busy++;
    o.innerHTML = `<div class="bub">${asked.replace(/</g,'&lt;')}</div><div class="mcx-a"><span class="wk"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Thinking</span></span></div>`;
    const a = $('.mcx-a', o);
    try {
      await c.wait(m.ms * .35); if (id !== col.run) return;
      const ws = (asked === DEF ? m.o : generic[col.m]).split(' '); a.innerHTML = '<span></span>'; const p = a.firstChild;
      for (const w of ws){ p.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await c.wait(m.ms * .65 / ws.length); if (id !== col.run) return; }
      f.innerHTML = `<span class="tm" data-tip="Time to finish, ${m.tps} tokens a second">${(m.ms / 1000).toFixed(1)}s</span><span class="co" data-tip="Cost of this reply">$${m.cost.toFixed(3)}</span>`; pk.disabled = false;
    } finally { busy--; if (!busy) badges(); }
  }
  /* once every column has answered, the fastest time and the lowest cost turn green */
  function badges(){
    go.disabled = sending || !q.value.trim();
    const done = C.filter(x => !$('.mcx-pick', x.el).disabled); if (done.length < 2) return;
    const fast = done.reduce((a, b) => MOD[b.m].ms < MOD[a.m].ms ? b : a), cheap = done.reduce((a, b) => MOD[b.m].cost < MOD[a.m].cost ? b : a);
    done.forEach(x => { const tm = $('.tm', x.el), co = $('.co', x.el);
      tm.classList.toggle('best', x === fast); tm.dataset.tip = (x === fast ? 'Fastest. ' : '') + 'Time to finish, ' + MOD[x.m].tps + ' tokens a second';
      co.classList.toggle('best', x === cheap); co.dataset.tip = x === cheap ? 'Cheapest reply' : 'Cost of this reply'; });
  }
  ['Opus','Sonnet','Haiku'].forEach(m => addCol(m)); sync();
  // Send stays off while a send is answering, even if the prompt changes
  let sending = false;
  const run = () => c.run(async () => { if (!q.value.trim()) return; asked = q.value.trim(); go.disabled = true; sending = true; try { await Promise.all(C.map(one)); } finally { sending = false; } go.disabled = !q.value.trim(); });
  $('.mcx-in', r).onsubmit = e => { e.preventDefault(); if (!sending) run(); };
  q.oninput = () => { go.disabled = sending || !q.value.trim(); };
  // the preview sends its question once on its own, unless you take over first
  c.auto(1200, run);
});
